const CACHE='an-vui-v8';const CORE=['./','./index.html','./style.css','./app.js','./features.js','./manifest.webmanifest','./assets/icon.svg','./assets/icon-192.png','./assets/icon-512.png','./assets/apple-touch-icon.png','./assets/zentech-mark.webp','./assets/zentech-logo.webp','./assets/qr-app.svg','./assets/avatars/minh.webp','./assets/avatars/huong.webp','./assets/avatars/mai.webp','./assets/avatars/lan.webp','./assets/avatars/minhanh.webp','./assets/community.webp','./assets/campaign-story.webp','./assets/campaign-story.jpg','./assets/campaign-keyvisual.webp','./assets/garden.webp','./assets/tea.webp','./assets/cup.webp','./assets/lamp.webp','./assets/chess.webp','./assets/fonts.css','./assets/fonts/bevietnam-2.ttf','./assets/fonts/bevietnam-3.ttf','./assets/fonts/bevietnam-1.ttf','./assets/fonts/bevietnam-0.ttf'];self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(CORE)));self.skipWaiting()});self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==location.origin)return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy))}return r}).catch(()=>caches.match(e.request).then(r=>r||(e.request.mode==='navigate'?caches.match('./index.html'):Response.error()))))});
